import React, { useState, useEffect, useMemo, useRef } from 'react'
import AdaptableCard from 'components/shared/AdaptableCard'
import DataTable from 'components/shared/DataTable'
import debounce from 'lodash/debounce'
import Button from 'components/ui/Buttons'
import Input from 'components/ui/Input'
import { MdCreate, MdDelete, } from "react-icons/md"
import { useNavigate } from 'react-router-dom'
import { HiSearch } from 'react-icons/hi'
import { apiCategoryDelete, apiCategoryGet, apiCategoryPost, apiCategoryUpdate } from 'services/CategoryService'
import Dialog from 'components/ui/Dialog'
import toast from 'components/ui/toast'
import Notification from 'components/ui/Notification'
import { FormItem, FormContainer } from 'components/ui'
import ConfirmDialog from 'components/shared/ConfirmDialog'
import { Field, Form, Formik } from 'formik'
import { useDispatch } from 'react-redux'
import { setUser, initialState } from 'store/auth/userSlice'
import { onSignOutSuccess } from 'store/auth/sessionSlice'
import appConfig from 'configs/app.config'

const Category = () => {
    const [data, setData] = useState([])
    const [loading, setLoading] = useState(false)
    const [tableData, setTableData] = useState({
        total: 0,
        pageIndex: 1,
        pageSize: 10,
        query: '',
        sort: {
            order: '',
            key: '',
        },
    });
    const [categoryData, setCategoryData] = useState({ category_name: '' })
    const navigate = useNavigate();
    const inputRef = useRef(null)
    const [addEdit, setAddEdit] = useState('');
    const [open, setOpen] = useState(false)
    const [deleteId, setDeleteId] = useState(null);

    const debounceFn = debounce(handleDebounceFn, 1000)

    function handleDebounceFn(val) {
        if (typeof val === 'string' && (val.length > 1 || val.length === 0)) {
            setTableData((prevData) => ({
                ...prevData,
                ...{ query: val, pageIndex: 1 },
            }))
        }
    }

    const handleChange = (e) => {
        debounceFn(e.target.value)
    }

    const handleRowClick = (data) => {
        // navigate(`/product/product/edit-product/${dataid}`);
        console.log(data);
        openDialog();
        setAddEdit(data.id);
        setCategoryData({
            category_name: data.category_name,
        })
    }

    const onDialogClose1 = (e) => {
        console.log('onDialogClose', e)
        setOpen(false)
    }

    const onDialogOk1 = (e) => {
        console.log('onDialogOk', e)
        apiCategoryDelete(deleteId).then(data => {
            console.log(data);
            if (data.status === 200) {
                toast.push(
                    <Notification
                        title='Success'
                        type='success'
                        closable
                    >
                        {data.data['message']}
                    </Notification>
                )
                setLoading(true)
                setOpen(false)
                apiCategoryGet(tableData).then(data => {
                    if (data.data) {
                        console.log(data.data)
                        setData(data.data['rows'])
                        setLoading(false)
                        setTableData((prevData) => ({
                            ...prevData,
                            ...{ total: data.data['total'] },
                        }))
                    }
                }).catch(error => {
                    console.log(error);
                })
            }
        }).catch(error => {
            console.log(error);
        })

    }


    const handleDeleteRowClick = (dataId) => {
        setDeleteId(dataId);
        setOpen(true)
    }

    const [dialogIsOpen, setIsOpen] = useState(false)

    const openDialog = () => {
        setAddEdit('');
        setCategoryData({ category_name: '' })
        setIsOpen(true)
    }

    const onDialogClose = (e) => {
        console.log('onDialogClose', e)
        setIsOpen(false)
    }

    const columns = useMemo(() => (
        [
            {
                header: 'Sr. No.',
                cell: ((props) => props.row.index + 1),
                width: 70

            },
            {
                header: 'Category Name',
                accessorKey: 'category_name',
            },
            {
                header: 'Status',
                accessorKey: 'status',
                cell: (props) => (props.row.original.status ? 'Active' : 'Deleted'),
                width: 123
            },
            {
                header: 'Action',
                width: 135,
                cell: (props) => (
                    <>
                        <Button
                            shape="circle"
                            size="sm"
                            variant="twoTone"
                            icon={<MdCreate />}
                            className='mr-3'
                            onClick={() => { handleRowClick(props.row.original) }}
                        />
                        <Button
                            shape="circle"
                            size="sm"
                            variant="twoTone"
                            color="red-600"
                            icon={<MdDelete />}
                            onClick={() => { handleDeleteRowClick(props.row.original.id) }}
                        />
                    </>
                ),
            },
        ]
    ), [])

    const handlePaginationChange = (pageIndex) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageIndex } }))
    }

    const handleSelectChange = (pageSize) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageSize } }))
    }

    const handleSort = ({ order, key }) => {
        setTableData((prevData) => ({
            ...prevData,
            ...{ sort: { order, key } },
        }))
    }

    function validateCategory(value) {
        if (!value) {
            return 'Required'
        }
        return
    }

    const dispatch = useDispatch()

    useEffect(() => {

        const fetchData = async () => {
            setLoading(true)
            const data = await apiCategoryGet(tableData).catch(error => {
                if (error.response.status === 500) {
                    console.log(error)
                    toast.push(
                        <Notification
                            title='Failed'
                            type='warning'
                            closable
                        >
                            {error.response.data['message']}
                        </Notification>
                    )
                    setLoading(false);
                } else if (error.response.status === 400) {
                    dispatch(onSignOutSuccess())
                    dispatch(setUser(initialState))
                    navigate(appConfig.unAuthenticatedEntryPath)
                }
            });
            if (data.data) {
                console.log(data.data)
                setData(data.data['rows'])
                setLoading(false)
                setTableData((prevData) => ({
                    ...prevData,
                    ...{ total: data.data['total'] },
                }))
            }
        }
        fetchData()
        // eslint-disable-next-line react-hooks/exhaustive-deps

    }, [tableData.pageIndex, tableData.sort, tableData.pageSize, tableData.query])
    return (
        <AdaptableCard className="card-shadow">
            <div className='lg:flex items-center justify-between mb-4'>
                <h3 className="mb-4 lg:mb-0 ">Category</h3>
                <div className='flex flex-col lg:flex-row lg:items-center'>
                    <Input
                        ref={inputRef}
                        placeholder="Search..."
                        size="sm"
                        className="lg:w-52 mr-4 lg:mb-0 "
                        onChange={handleChange}
                        prefix={<HiSearch className="text-lg" />}
                    />
                    <Button variant="solid" size="sm" onClick={() => openDialog()}>
                        Add Category
                    </Button>
                    <Dialog
                        isOpen={dialogIsOpen}
                        shouldCloseOnOverlayClick={false}
                        shouldCloseOnEsc={false}
                        onClose={onDialogClose}
                        onRequestClose={onDialogClose}
                    >
                        <h5 className=" mb-6">{addEdit === '' ? 'Add' : 'Edit'} Category</h5>
                        <Formik
                            enableReinitialize={true}
                            initialValues={categoryData}
                            onSubmit={(values, actions) => {
                                if (addEdit === '') {
                                    apiCategoryPost(values).then(data => {
                                        toast.push(
                                            <Notification
                                                title='Success'
                                                type='success'
                                                closable
                                            >
                                                {data.data['message']}
                                            </Notification>
                                        )
                                        actions.setSubmitting(false)
                                        setIsOpen(false)
                                        setLoading(true);
                                        apiCategoryGet(tableData).then(data => {
                                            if (data.data) {
                                                console.log(data.data)
                                                setData(data.data['rows'])
                                                setLoading(false)
                                                setTableData((prevData) => ({
                                                    ...prevData,
                                                    ...{ total: data.data['total'] },
                                                }))
                                            }
                                        }).catch(error => {
                                            console.log(error);
                                        })
                                    }).catch(error => {
                                        let errorData = error.response['data']['error']['errors'];
                                        actions.setSubmitting(false)
                                        if (error.response.status === 422) {
                                            for (const errMsg in errorData) {
                                                actions.setFieldError('category_name', errorData[errMsg]['message'])
                                                toast.push(
                                                    <Notification
                                                        title='Error'
                                                        type='danger'
                                                        closable
                                                    >
                                                        {errorData[errMsg]['message']}

                                                    </Notification>
                                                )
                                            }
                                        } else if (error.response.status === 500) {
                                            console.log(errorData)
                                        }
                                    })
                                } else {
                                    apiCategoryUpdate({ ...{ id: addEdit }, values }).then(data => {
                                        toast.push(
                                            <Notification
                                                title='Success'
                                                type='success'
                                                closable
                                            >
                                                {data.data['message']}
                                            </Notification>
                                        )
                                        actions.setSubmitting(false)
                                        setIsOpen(false)
                                        setLoading(true);
                                        apiCategoryGet(tableData).then(data => {
                                            if (data.data) {
                                                console.log(data.data)
                                                setData(data.data['rows'])
                                                setLoading(false)
                                                setTableData((prevData) => ({
                                                    ...prevData,
                                                    ...{ total: data.data['total'] },
                                                }))
                                            }
                                        }).catch(error => {
                                            console.log(error);
                                        })
                                    }).catch(error => {
                                        let errorData = error.response['data']['error']['errors'];
                                        actions.setSubmitting(false)
                                        if (error.response.status === 422) {
                                            for (const errMsg in errorData) {
                                                actions.setFieldError('category_name', errorData[errMsg]['message'])
                                                toast.push(
                                                    <Notification
                                                        title='Error'
                                                        type='danger'
                                                        closable
                                                    >
                                                        {errorData[errMsg]['message']}

                                                    </Notification>
                                                )
                                            }
                                        } else if (error.response.status === 500) {
                                            console.log(errorData)
                                        }
                                    })
                                }
                            }}
                        >
                            {({ errors, touched, isSubmitting }) => (
                                <Form>
                                    <FormContainer>
                                        <FormItem
                                            invalid={errors.category_name && touched.category_name}
                                            errorMessage={errors.category_name}
                                        >
                                            <Field
                                                type="text"
                                                name="category_name"
                                                placeholder="Category Name"
                                                component={Input}
                                                validate={validateCategory}
                                            />
                                        </FormItem>
                                        <FormItem className="text-right">
                                            <Button
                                                className="ltr:mr-2 rtl:ml-2"
                                                variant="plain"
                                                type="button"
                                                onClick={onDialogClose}
                                            >
                                                Cancel
                                            </Button>
                                            <Button type="submit" variant="solid" disabled={isSubmitting}>
                                                Submit
                                            </Button>
                                        </FormItem>
                                    </FormContainer>
                                </Form>
                            )}
                        </Formik>
                    </Dialog>
                </div>
            </div>
            <DataTable
                columns={columns}
                data={data}
                loading={loading}
                pagingData={tableData}
                onPaginationChange={handlePaginationChange}
                onSelectChange={handleSelectChange}
                onSort={handleSort}
            />
            <ConfirmDialog
                isOpen={open}
                closable={false}
                type='danger'
                title="Delete Product!!"
                onClose={onDialogClose1}
                onRequestClose={onDialogClose1}
                onCancel={onDialogClose1}
                onConfirm={onDialogOk1}
                confirmButtonColo="red-600">
                <p>
                    Do you want to delete this product ?
                </p>
            </ConfirmDialog>
        </AdaptableCard>
    )
}

export default Category
